-- ============================================================
-- STUDENT schema (Oracle 'SQL by Example' DB) -- PostgreSQL version
-- Converted from the MySQL/SQL Server script for IS 402. 
-- Loads as a SCHEMA named 'student' (matches the other course DBs).
-- Query with:  SET search_path TO student;
-- ============================================================

/*****************************************************************
  File:        SQLServerCreateStudent.sql
  Description: Used for creating the objects and loading data
               into the STUDENT schema for MSSQL
  Created:     August 10, 2016 RBH
  Modified:    August 10, 2016 RBH
  Version:     1.0
******************************************************************/
CREATE SCHEMA IF NOT EXISTS student;
SET search_path TO student;

---- Creating Table 'INSTRUCTOR'
CREATE TABLE INSTRUCTOR
 (INSTRUCTOR_ID NUMERIC(8,0) PRIMARY KEY
 ,SALUTATION VARCHAR(5)
 ,FIRST_NAME VARCHAR(25)
 ,LAST_NAME VARCHAR(25)
 ,STREET_ADDRESS VARCHAR(50)
 ,ZIP VARCHAR(5)
 ,PHONE VARCHAR(15)
 ,CREATED_BY VARCHAR(30) NOT NULL
 ,CREATED_DATE TIMESTAMP NOT NULL
 ,MODIFIED_BY VARCHAR(30) NOT NULL
 ,MODIFIED_DATE TIMESTAMP NOT NULL
 );

-- Creating Table 'GRADE'
CREATE TABLE GRADE
 (STUDENT_ID NUMERIC(8,0) 
 ,SECTION_ID NUMERIC(8,0) 
 ,GRADE_TYPE_CODE VARCHAR(2) NOT NULL
 ,GRADE_CODE_OCCURRENCE NUMERIC(38,0) NOT NULL
 ,NUMERIC_GRADE NUMERIC(3,0) DEFAULT 0 NOT NULL
 ,COMMENTS VARCHAR(2000)
 ,CREATED_BY VARCHAR(30) NOT NULL
 ,CREATED_DATE TIMESTAMP NOT NULL
 ,MODIFIED_BY VARCHAR(30) NOT NULL
 ,MODIFIED_DATE TIMESTAMP NOT NULL
 ,CONSTRAINT PK_GRADE PRIMARY KEY(STUDENT_ID,SECTION_ID, GRADE_TYPE_CODE, GRADE_CODE_OCCURRENCE)
 );

-- Creating Table 'GRADE_TYPE'
CREATE TABLE GRADE_TYPE
 (GRADE_TYPE_CODE VARCHAR(2) PRIMARY KEY
 ,DESCRIPTION VARCHAR(50) NOT NULL
 ,CREATED_BY VARCHAR(30) NOT NULL
 ,CREATED_DATE TIMESTAMP NOT NULL
 ,MODIFIED_BY VARCHAR(30) NOT NULL
 ,MODIFIED_DATE TIMESTAMP NOT NULL
 );

-- Creating Table 'GRADE_CONVERSION'
CREATE TABLE GRADE_CONVERSION
 (LETTER_GRADE VARCHAR(2) NOT NULL
 ,GRADE_POINT NUMERIC(3,2) DEFAULT 0 NOT NULL
 ,MAX_GRADE NUMERIC(3,0) NOT NULL
 ,MIN_GRADE NUMERIC(3,0) NOT NULL
 ,CREATED_BY VARCHAR(30) NOT NULL
 ,CREATED_DATE TIMESTAMP NOT NULL
 ,MODIFIED_BY VARCHAR(30) NOT NULL
 ,MODIFIED_DATE TIMESTAMP  NOT NULL
 );

-- Creating Table 'GRADE_TYPE_WEIGHT'
CREATE TABLE GRADE_TYPE_WEIGHT
 (SECTION_ID NUMERIC(8,0) 
 ,GRADE_TYPE_CODE VARCHAR(2) 
 ,NUMBER_PER_SECTION NUMERIC(4,0) NOT NULL
 ,PERCENT_OF_FINAL_GRADE NUMERIC(4,0) NOT NULL
 ,DROP_LOWEST VARCHAR(2) NOT NULL
 ,CREATED_BY VARCHAR(30) NOT NULL
 ,CREATED_DATE TIMESTAMP NOT NULL
 ,MODIFIED_BY VARCHAR(30) NOT NULL
 ,MODIFIED_DATE TIMESTAMP NOT NULL
 ,CONSTRAINT PK_GRADE_TYPE_WEIGHT PRIMARY KEY(SECTION_ID, GRADE_TYPE_CODE)
 );

-- Creating Table 'SECTION'
CREATE TABLE SECTION
 (SECTION_ID NUMERIC(8,0) PRIMARY KEY
 ,COURSE_NO NUMERIC(8,0) NOT NULL
 ,SECTION_NO NUMERIC(3,0) NOT NULL
 ,START_DATE_TIME TIMESTAMP
 ,LOCATION VARCHAR(50)
 ,INSTRUCTOR_ID NUMERIC(8,0) NOT NULL
 ,CAPACITY NUMERIC(3,0)
 ,CREATED_BY VARCHAR(30)  NOT NULL
 ,CREATED_DATE TIMESTAMP NOT NULL
 ,MODIFIED_BY VARCHAR(30) NOT NULL
 ,MODIFIED_DATE TIMESTAMP NOT NULL
 );

-- Creating Table 'COURSE'
CREATE TABLE COURSE
 (COURSE_NO NUMERIC(8,0) PRIMARY KEY
 ,DESCRIPTION VARCHAR(50) NOT NULL
 ,COST NUMERIC(9,2) 
 ,PREREQUISITE NUMERIC(8,0)
 ,CREATED_BY VARCHAR(30) NOT NULL
 ,CREATED_DATE TIMESTAMP NOT NULL
 ,MODIFIED_BY VARCHAR(30) NOT NULL
 ,MODIFIED_DATE TIMESTAMP NOT NULL
 );

-- Creating Table 'ENROLLMENT'
CREATE TABLE ENROLLMENT
 (STUDENT_ID NUMERIC(8,0) 
 ,SECTION_ID NUMERIC(8,0) 
 ,ENROLL_DATE TIMESTAMP NOT NULL
 ,FINAL_GRADE NUMERIC(3,0)
 ,CREATED_BY VARCHAR(30) NOT NULL
 ,CREATED_DATE TIMESTAMP NOT NULL
 ,MODIFIED_BY VARCHAR(30) NOT NULL
 ,MODIFIED_DATE TIMESTAMP NOT NULL
 ,CONSTRAINT PK_ENROLLMENT PRIMARY KEY(STUDENT_ID, SECTION_ID)
 );


-- Creating Table 'STUDENT'
CREATE TABLE STUDENT
 (STUDENT_ID NUMERIC(8,0) PRIMARY KEY
 ,SALUTATION VARCHAR(5)
 ,FIRST_NAME VARCHAR(25)
 ,LAST_NAME VARCHAR(25) NOT NULL
 ,STREET_ADDRESS VARCHAR(50)
 ,ZIP VARCHAR(5) NOT NULL
 ,PHONE VARCHAR(15)
 ,EMPLOYER VARCHAR(50)
 ,REGISTRATION_DATE TIMESTAMP 
 ,CREATED_BY VARCHAR(30) NOT NULL
 ,CREATED_DATE TIMESTAMP NOT NULL
 ,MODIFIED_BY VARCHAR(30) NOT NULL
 ,MODIFIED_DATE TIMESTAMP NOT NULL
 );

-- Creating Table 'ZIPCODE'
CREATE TABLE ZIPCODE
 (ZIP VARCHAR(5) PRIMARY KEY
 ,CITY VARCHAR(25)
 ,STATE VARCHAR(2)
 ,CREATED_BY VARCHAR(30) NOT NULL
 ,CREATED_DATE TIMESTAMP NOT NULL
 ,MODIFIED_BY VARCHAR(30) NOT NULL
 ,MODIFIED_DATE TIMESTAMP NOT NULL
 );

--  student.ind

-- Creating Index 'INST_ZIP_FK_I'
CREATE INDEX INST_ZIP_FK_I ON INSTRUCTOR
 (ZIP);

-- Creating Index 'GR_GRTW_FK_I'
CREATE INDEX GR_GRTW_FK_I ON GRADE
 (SECTION_ID
 ,GRADE_TYPE_CODE);

-- Creating Index 'GRTW_GRTYP_FK_I'
CREATE INDEX GRTW_GRTYP_FK_I ON GRADE_TYPE_WEIGHT
 (GRADE_TYPE_CODE);

-- Creating Index 'SECT_CRSE_FK_I'
CREATE INDEX SECT_CRSE_FK_I ON SECTION
 (COURSE_NO);

-- Creating Index 'SECT_INST_FK_I'
CREATE INDEX SECT_INST_FK_I ON SECTION
 (INSTRUCTOR_ID);

-- Creating Index 'CRSE_CRSE_FK_I'
CREATE INDEX CRSE_CRSE_FK_I ON COURSE
 (PREREQUISITE);

-- Creating Index 'ENR_SECT_FK_I'
CREATE INDEX ENR_SECT_FK_I ON ENROLLMENT
 (SECTION_ID);

-- Creating Index 'STU_ZIP_FK_I'
CREATE INDEX STU_ZIP_FK_I ON STUDENT
 (ZIP);
