-- Add Constraints
-- ALTER TABLE Student DROP CONSTRAINT FK_StudentZip;
ALTER TABLE Student
	ADD CONSTRAINT FK_StudentZip FOREIGN KEY(zip) REFERENCES ZipCode(Zip);

-- ALTER TABLE Instructor DROP CONSTRAINT FK_InstructorZip;
ALTER TABLE Instructor
	ADD CONSTRAINT FK_InstructorZip FOREIGN KEY(zip) REFERENCES ZipCode(Zip);

-- ALTER TABLE Course DROP CONSTRAINT FK_CoursePrereq;
ALTER TABLE Course
	ADD CONSTRAINT FK_CoursePrereq FOREIGN KEY(prerequisite) REFERENCES  Course(Course_no);

-- ALTER TABLE Section DROP CONSTRAINT FK_SectionCourse;
ALTER TABLE Section
	ADD CONSTRAINT FK_SectionCourse FOREIGN KEY(Course_no) REFERENCES  Course(Course_no);

-- ALTER TABLE Enrollment DROP CONSTRAINT FK_EnrollmentSection;
ALTER TABLE Enrollment
	ADD CONSTRAINT FK_EnrollmentSection FOREIGN KEY(section_id) REFERENCES  Section(Section_id);

-- ALTER TABLE Enrollment DROP CONSTRAINT FK_EnrollmentStudent;
ALTER TABLE Enrollment
	ADD CONSTRAINT FK_EnrollmentStudent FOREIGN KEY(student_id) REFERENCES  Student(Student_id);

-- ALTER TABLE  Grade_Type_Weight	DROP CONSTRAINT FK_GTWSection;
ALTER TABLE  Grade_Type_Weight
	ADD CONSTRAINT FK_GTWSection FOREIGN KEY(Section_id) REFERENCES  Section(Section_id);

-- ALTER TABLE Grade_Type_Weight DROP CONSTRAINT FK_GTWGradeType;
ALTER TABLE Grade_Type_Weight
	ADD CONSTRAINT FK_GTWGradeType FOREIGN KEY(Grade_Type_Code) REFERENCES  Grade_Type(Grade_Type_Code);

-- ALTER TABLE  Grade DROP CONSTRAINT FK_GradeEnrollment;
ALTER TABLE  Grade
	ADD CONSTRAINT FK_GradeEnrollment FOREIGN KEY(Student_ID, Section_Id) REFERENCES  Enrollment(Student_ID, Section_Id);

-- ALTER TABLE Grade DROP CONSTRAINT FK_GradeGTW;
ALTER TABLE Grade
	ADD CONSTRAINT FK_GradeGTW FOREIGN KEY(Section_id, Grade_Type_Code) REFERENCES Grade_Type_Weight(Section_id, Grade_Type_Code);